def solve():
    fixed = {1: -1, 6: 1, 9: -1}

    def get_seq(bits):
        seq = []
        bit_idx = 0
        for i in range(17):
            if i in fixed:
                seq.append(fixed[i])
            else:
                seq.append(1 if (bits & (1 << bit_idx)) else -1)
                bit_idx += 1
        return seq

    for bits in range(1 << 14):
        seq = get_seq(bits)

        # Check sum of C_k^2 <= 40
        energy = 0
        for k in range(1, 17):
            ck = sum(seq[i]*seq[i+k] for i in range(17-k))
            energy += ck**2
            if energy > 40:
                break

        if energy <= 40:
            c7 = sum(seq[i]*seq[i+7] for i in range(17-7))
            c8 = sum(seq[i]*seq[i+8] for i in range(17-8))
            c12 = sum(seq[i]*seq[i+12] for i in range(17-12))
            print("Found:", seq)
            print("Energy:", energy)
            print("c7:", c7, "c8:", c8, "c12:", c12)

solve()
